-- =====================================================================
-- FalaBrincando - BIBLIOTECA DE FONEMAS (15 fonemas novos)
-- Portuguese brasileiro: P, B, T, D, K, G, F, V, M, N, NH, J, Z, CH, QU
--
-- Cada fonema tem 12 ou mais palavras com posicao e silabacao.
-- Modelos globais (fono_id NULL): a fonoaudióloga duplica para adaptar.
-- Pode reimportar: usa INSERT IGNORE.
-- =====================================================================

INSERT IGNORE INTO phonemes
 (id, fono_id, symbol, name, kind, ipa, sound_model, description, variation_ptbr,
  target_positions, syllables, combinations, words, sentences,
  guardian_instructions, objectives, followup_criteria)
VALUES

-- ================= P =================
(6, NULL,'P','''p''','consoante','/p/',
 'Fechar os lábios com força e soltar o ar de uma vez, num sopro curto.',
 'Produção do /p/ bilabial surdo nas três posições da palavra.',
 'Em português brasileiro o P inicial e medial é /p/. O P final costuma vocalizar-se, como em «sapato» (/sapatu/), por isso é treinado com apoio.',
 '["inicial","medial","final"]',
 '["pa","pe","pi","po","pu","pa-ta","pi-na"]',
 '["pa-se","pe-lo","a-pa"]',
 '[{"word":"pão","position":"inicial","syllables":["pão"]},{"word":"pato","position":"inicial","syllables":["pa","to"]},{"word":"pente","position":"inicial","syllables":["pen","te"]},{"word":"peixe","position":"inicial","syllables":["pei","xe"]},{"word":"porta","position":"inicial","syllables":["por","ta"]},{"word":"praia","position":"inicial","syllables":["prai","a"]},{"word":"preto","position":"inicial","syllables":["pre","to"]},{"word":"pulo","position":"inicial","syllables":["pu","lo"]},{"word":"pé","position":"inicial","syllables":["pé"]},{"word":"pipa","position":"inicial","syllables":["pi","pa"]},{"word":"mala","position":"medial","syllables":["ma","la"]},{"word":"sapo","position":"medial","syllables":["sa","po"]},{"word":"toupeira","position":"medial","syllables":["to","pei","ra"]},{"word":"lapela","position":"medial","syllables":["la","pe","la"]}]',
 '["O pão está na mesa.","A pata do pato é grande.","O peixe nada no mar.","A porta está fechada.","A menina está na praia."]',
 'Sente-se ao lado e produza o som junto. Segure a respiração e solte o ar com força. Se a criança travar, encoste os lábios no dedo do profissional e produza junto.',
 'Produzir /p/ isolado, em sílabas, palavras e frases.',
 'Avançar quando produzir 8 de 10 palavras com apenas o modelo adulto.'),

-- ================= B =================
(7, NULL,'B','''b''','consoante','/b/',
 'Fechar os lábios, tremer levemente e abrir sozinha para a vibração aparecer.',
 'Produção do /b/ bilabial sonoro nas três posições.',
 'O B medial e final tendem a realiza-se como vogal na fala spontaneous do português brasileiro (maria/madria). Treinar explicitamente a versão bilabial.',
 '["inicial","medial","final"]',
 '["ba","be","bi","bo","bu","bi-lho"]',
 '["ba-bo","a-bra"]',
 '[{"word":"bola","position":"inicial","syllables":["bo","la"]},{"word":"boca","position":"inicial","syllables":["bo","ca"]},{"word":"bolsa","position":"inicial","syllables":["bol","sa"]},{"word":"branco","position":"inicial","syllables":["bran","co"]},{"word":"banho","position":"inicial","syllables":["ba","nho"]},{"word":"barco","position":"inicial","syllables":["bar","co"]},{"word":"bicho","position":"inicial","syllables":["bi","cho"]},{"word":"balão","position":"inicial","syllables":["ba","lão"]},{"word":"braço","position":"inicial","syllables":["bra","ço"]},{"word":"bebida","position":"inicial","syllables":["be","bi","da"]},{"word":"cabeca","position":"medial","syllables":["ca","be","ca"]},{"word":"rabo","position":"medial","syllables":["ra","bo"]},{"word":"trombeta","position":"medial","syllables":["trom","be","ta"]},{"word":"subir","position":"medial","syllables":["su","bir"]}]',
 '["A bola é redonda.","O cachorro late.","A boca está fechada.","O barco chegou.","A menina toma banho."]',
 'Faça o som junto, sem pedir correção. Valorize a tentativa e mantenha o tom acolhedor. Lábios bem fechados e tremendo.',
 'Produzir /b/ isolado, em sílabas, palavras e frases.',
 'Avançar com 8 de 10 palavras realizadas de forma bilabial.'),

-- ================= T =================
(8, NULL,'T','''t''','consoante','/t/',
 'Encostar a ponta da língua atrás dos dentes de cima e soltar o ar com força.',
 'Produção do /t/ dental nas três posições.',
 'No português brasileiro o T é dental (a ponta da língua toca atrás dos dentes), diferente do inglês.',
 '["inicial","medial","final"]',
 '["ta","te","ti","to","tu","tu-do"]',
 '["to-na","a-tu"]',
 '[{"word":"teia","position":"inicial","syllables":["tei","a"]},{"word":"tela","position":"inicial","syllables":["te","la"]},{"word":"tempo","position":"inicial","syllables":["tem","po"]},{"word":"tomate","position":"inicial","syllables":["to","ma","te"]},{"word":"tatu","position":"inicial","syllables":["ta","tu"]},{"word":"tigre","position":"inicial","syllables":["ti","gre"]},{"word":"trio","position":"inicial","syllables":["tri","o"]},{"word":"tarde","position":"inicial","syllables":["tar","de"]},{"word":"turista","position":"inicial","syllables":["tu","ris","ta"]},{"word":"talher","position":"inicial","syllables":["ta","lher"]},{"word":"bota","position":"medial","syllables":["bo","ta"]},{"word":"mate","position":"medial","syllables":["ma","te"]},{"word":"roto","position":"medial","syllables":["ro","to"]},{"word":"rato","position":"final","syllables":["ra","to"]}]',
 '["A teia é doaranjo.","A tela está limpa.","O tempo está frio.","O tomate é vermelho.","O ratinho é pequeno."]',
 'Mostre onde a língua toca (use espelho se ajudar). Produza junto primeiro e depois espere a criança.',
 'Produzir /t/ dental isolado, em sílabas, palavras e frases.',
 'Avançar quando a ponta da língua tocar atrás dos dentes em 8 de 10 tentativas.'),

-- ================= D =================
(9, NULL,'D','''d''','consoante','/d/',
 'Encostar a ponta da língua atrás dos dentes de cima e soltar o ar deixando a voz vibrar.',
 'Produção do /d/ dental nas três posições.',
 'Como o T, o D é dental no português brasileiro. O D final costuma vocalizar-se.',
 '["inicial","medial","final"]',
 '["da","de","di","do","du","da-do"]',
 '["do-me","a-deu"]',
 '[{"word":"dedal","position":"inicial","syllables":["de","dal"]},{"word":"dente","position":"inicial","syllables":["den","te"]},{"word":"dona","position":"inicial","syllables":["do","na"]},{"word":"duro","position":"inicial","syllables":["du","ro"]},{"word":"dois","position":"inicial","syllables":["dois"]},{"word":"desenho","position":"inicial","syllables":["de","se","nho"]},{"word":"domingo","position":"inicial","syllables":["do","min","go"]},{"word":"dinossauro","position":"inicial","syllables":["di","nos","sau","ro"]},{"word":"diabo","position":"inicial","syllables":["di","a","bo"]},{"word":"dragão","position":"inicial","syllables":["dra","gão"]},{"word":"mesa","position":"medial","syllables":["me","sa"]},{"word":"cidade","position":"medial","syllables":["ci","da","de"]},{"word":"lado","position":"final","syllables":["la","do"]},{"word":"verde","position":"final","syllables":["ver","de"]}]',
 '["O dente está branco.","A dona está em casa.","O desenho é bonito.","O dragão voa alto.","A mesa é de madeira."]',
 'Produza o som junto duas vezes e depois espere. Não peça para repetir muitas vezes seguidas.',
 'Produzir /d/ dental isolado, em sílabas, palavras e frases.',
 'Avançar com 8 de 10 palavras com som bilateral correto.'),

-- ================= K (C antes de A, O, U) =================
(10, NULL,'K','''K (C antes de A, O, U)''','consoante','/k/',
 'Tocar o fundo da boca com o dorso da língua e soltar o ar com força.',
 'Produção do /k/ velar surdo.',
 'A letra C soa /k/ antes de A, O e U, e /s/ antes de E, I. Mesmo fonema, grafemas diferentes: modelar a partir do som, não da letra.',
 '["inicial","medial"]',
 '["ca","co","cu","ca-sa","ca-ta"]',
 '["ca-sa","co-me"]',
 '[{"word":"casa","position":"inicial","syllables":["ca","sa"]},{"word":"cavalo","position":"inicial","syllables":["ca","va","lo"]},{"word":"carro","position":"inicial","syllables":["ca","rro"]},{"word":"gato","position":"inicial","syllables":["ga","to"]},{"word":"vaca","position":"inicial","syllables":["va","ca"]},{"word":"camelo","position":"inicial","syllables":["ca","me","lo"]},{"word":"cabra","position":"inicial","syllables":["ca","bra"]},{"word":"coruja","position":"inicial","syllables":["co","ru","ja"]},{"word":"cuidado","position":"inicial","syllables":["cui","da","do"]},{"word":"careta","position":"inicial","syllables":["ca","re","ta"]},{"word":"copo","position":"inicial","syllables":["co","po"]},{"word":"teatro","position":"medial","syllables":["te","a","tro"]},{"word":"seco","position":"medial","syllables":["se","co"]},{"word":"pequeno","position":"medial","syllables":["pe","que","no"]}]',
 '["A casa é azul.","O cavalo corre rápido.","O carro é vermelho.","O gato dorme no sofá.","A vaca está no pasto."]',
 'Lembre que o mesmo som pode ter letras diferentes (C, K, QU, G antes de E/I). A criança precisa do som, não da letra.',
 'Produzir /k/ isolado, em sílabas e palavras.',
 'Avançar quando reconhecer o mesmo som em grafemas diferentes.'),

-- ================= G =================
(11, NULL,'G','''G''','consoante','/g/',
 'Tocar o fundo da boca com o dorso da língua e soltar o ar deixando a voz vibrar.',
 'Produção do /g/ velar sonoro.',
 'G soa /g/ antes de E e I, e /ʒ/ antes de E/I em palavras como «gelo». O G inicial antes de E/I é o caso típico de produção.',
 '["inicial","medial"]',
 '["ga","ge","gi","go","gu","go-lo"]',
 '["ge-lo","gui-a"]',
 '[{"word":"gelo","position":"inicial","syllables":["ge","lo"]},{"word":"girafa","position":"inicial","syllables":["gi","ra","fa"]},{"word":"gola","position":"inicial","syllables":["go","la"]},{"word":"gota","position":"inicial","syllables":["go","ta"]},{"word":"galinha","position":"inicial","syllables":["ga","li","nha"]},{"word":"guerra","position":"inicial","syllables":["ger","ra"]},{"word":"giz","position":"inicial","syllables":["giz"]},{"word":"gordo","position":"inicial","syllables":["gor","do"]},{"word":"goleiro","position":"inicial","syllables":["go","lei","ro"]},{"word":"guia","position":"inicial","syllables":["gui","a"]},{"word":"agulha","position":"medial","syllables":["a","gu","lha"]},{"word":"lago","position":"medial","syllables":["la","go"]},{"word":"cogumelo","position":"medial","syllables":["co","gu","me","lo"]},{"word":"tigre","position":"medial","syllables":["ti","gre"]}]',
 '["O gelo está frio.","A girafa tem pescoço longo.","A galinha põe ovos.","O lago é calmo.","O giz escreve na parede."]',
 'Produza o som e peça para sentir a vibração na garganta (coloque a mão no pescoço). Sem forçar.',
 'Produzir /g/ isolado, em sílabas, palavras e frases.',
 'Avançar quando produzir com vibração perceptível em 8 de 10 palavras.'),

-- ================= F =================
(12, NULL,'F','''f''','consoante','/f/',
 'Encostar o lábio superior nos dentes inferiores e soprar o ar.',
 'Produção do /f/ labiodental surdo.',
 'No português brasileiro o V também é labiodental; a diferença é de voz (F surdo, V sonoro), não de lugar de articulação.',
 '["inicial","medial","final"]',
 '["fa","fe","fi","fo","fu","fio-ho"]',
 '["fe-ro","a-fa"]',
 '[{"word":"faca","position":"inicial","syllables":["fa","ca"]},{"word":"farol","position":"inicial","syllables":["fa","rol"]},{"word":"fazenda","position":"inicial","syllables":["fa","zen","da"]},{"word":"figura","position":"inicial","syllables":["fi","gu","ra"]},{"word":"filtro","position":"inicial","syllables":["fil","tro"]},{"word":"folha","position":"inicial","syllables":["fo","lha"]},{"word":"filho","position":"inicial","syllables":["fi","lho"]},{"word":"flauta","position":"inicial","syllables":["flau","ta"]},{"word":"fruta","position":"inicial","syllables":["fru","ta"]},{"word":"feliz","position":"inicial","syllables":["fe","liz"]},{"word":"festa","position":"inicial","syllables":["fes","ta"]},{"word":"sofá","position":"medial","syllables":["so","fá"]},{"word":"café","position":"final","syllables":["ca","fé"]},{"word":"sufada","position":"final","syllables":["su","fa","da"]}]',
 '["A faca está na mesa.","O farol brilha.","A fazenda é grande.","A folha é verde.","O filho está brincando."]',
 'Positione os lábios nos dentes e sopre. Você pode pedir para sentir o ar na frente da boca.',
 'Produzir /f/ isolado, em sílabas, palavras e frases.',
 'Avançar quando produzir sem apoio em 8 de 10 palavras.'),

-- ================= V =================
(13, NULL,'V','''v''','consoante','/v/',
 'Encostar o lábio superior nos dentes inferiores e fazer vibrar as cordas vocais.',
 'Produção do /v/ labiodental sonoro.',
 'Contraste com o F: mesmo lugar de articulação, mas com voz. Verificar com a mão no pescoço.',
 '["inicial","medial","final"]',
 '["va","ve","vi","vo","vu","vo-r"]',
 '["ve-ro","a-vi"]',
 '[{"word":"vela","position":"inicial","syllables":["ve","la"]},{"word":"vento","position":"inicial","syllables":["ven","to"]},{"word":"vidro","position":"inicial","syllables":["vi","dro"]},{"word":"violão","position":"inicial","syllables":["vi","o","lão"]},{"word":"vinte","position":"inicial","syllables":["vin","te"]},{"word":"vovô","position":"inicial","syllables":["vo","vô"]},{"word":"viagem","position":"inicial","syllables":["via","gem"]},{"word":"vazio","position":"inicial","syllables":["va","zi","o"]},{"word":"veio","position":"inicial","syllables":["vei","o"]},{"word":"vez","position":"inicial","syllables":["vez"]},{"word":"ave","position":"medial","syllables":["a","ve"]},{"word":"salva","position":"medial","syllables":["sal","va"]},{"word":"navio","position":"medial","syllables":["na","vi","o"]},{"word":"lavar","position":"final","syllables":["la","var"]}]',
 '["A vela está acesa.","O vento é forte.","O vidro é transparente.","A viagem foi longa.","O vovô conta histórias."]',
 'Peça para sentir a vibração (mão no pescoço). Contraste com o F: /f/ sem voz, /v/ com voz.',
 'Produzir /v/ isolado, em sílabas, palavras e frases.',
 'Avançar quando diferenciar /v/ de /f/ em 8 de 10 pares.'),

-- ================= M =================
(14, NULL,'M','''m''','consoante','/m/',
 'Fechar os lábios e deixar o ar sair pelo nariz, com voz.',
 'Produção do /m/ bilabial nasal.',
 'O M final costuma nasalizar a vogal anterior (ex.: «bom»).',
 '["inicial","medial","final"]',
 '["ma","me","mi","mo","mu","mão"]',
 '["me-u","a-mor"]',
 '[{"word":"mão","position":"inicial","syllables":["mão"]},{"word":"mesa","position":"inicial","syllables":["me","sa"]},{"word":"mala","position":"inicial","syllables":["ma","la"]},{"word":"mãe","position":"inicial","syllables":["mãe"]},{"word":"morango","position":"inicial","syllables":["mo","ran","go"]},{"word":"música","position":"inicial","syllables":["mú","si","ca"]},{"word":"maçã","position":"inicial","syllables":["ma","çã"]},{"word":"medo","position":"inicial","syllables":["me","do"]},{"word":"mundo","position":"inicial","syllables":["mun","do"]},{"word":"mel","position":"inicial","syllables":["mel"]},{"word":"chama","position":"final","syllables":["cha","ma"]},{"word":"cinema","position":"final","syllables":["ci","ne","ma"]},{"word":"tomate","position":"medial","syllables":["to","ma","te"]},{"word":"cama","position":"final","syllables":["ca","ma"]}]',
 '["A mão está suja.","A mesa é redonda.","A mala é grande.","A maçã é vermelha.","O mel é doce."]',
 'Lábios fechados, ar pelo nariz. Peça para sentir o ar na mão na frente da boca.',
 'Produzir /m/ isolado, em sílabas, palavras e frases.',
 'Avançar quando fechar os lábios corretamente em 8 de 10 palavras.'),

-- ================= N =================
(15, NULL,'N','''n''','consoante','/n/',
 'Encostar a ponta da língua atrás dos dentes de cima e deixar o ar sair pelo nariz.',
 'Produção do /n/ alveolar nasal.',
 'O N final também nasaliza a vogal anterior.',
 '["inicial","medial","final"]',
 '["na","ne","ni","no","nu","no-me"]',
 '["ne-ve","a-no"]',
 '[{"word":"nariz","position":"inicial","syllables":["na","riz"]},{"word":"nome","position":"inicial","syllables":["no","me"]},{"word":"noite","position":"inicial","syllables":["noi","te"]},{"word":"nuvem","position":"inicial","syllables":["nu","vem"]},{"word":"navio","position":"inicial","syllables":["na","vi","o"]},{"word":"ninho","position":"inicial","syllables":["ni","nho"]},{"word":"nove","position":"inicial","syllables":["no","ve"]},{"word":"nada","position":"inicial","syllables":["na","da"]},{"word":"neto","position":"inicial","syllables":["ne","to"]},{"word":"norte","position":"inicial","syllables":["nor","te"]},{"word":"cano","position":"final","syllables":["ca","no"]},{"word":"menino","position":"final","syllables":["me","ni","no"]},{"word":"janela","position":"medial","syllables":["ja","ne","la"]},{"word":"ponte","position":"final","syllables":["pon","te"]}]',
 '["O nariz está vermelho.","A noite é silenciosa.","A nuvem é branca.","O ninho tem ovos.","A janela está aberta."]',
 'Ponta da língua atrás dos dentes, ar pelo nariz. Contraste com M (lábios) e NH (meio da boca).',
 'Produzir /n/ isolado, em sílabas, palavras e frases.',
 'Avançar quando diferenciar /n/, /m/ e /nh/ em 6 de 8 itens.'),

-- ================= NH =================
(16, NULL,'NH','''nh''','grupo_consonantal','/ʎ/',
 'Encostar o dorso da língua no meio do céu da boca e deixar o ar sair pelo nariz.',
 'Produção do /ʎ/ nasal palatal (digrafo NH).',
 'O NH é o som do N seguido de H. Em alguns dialetos aproxima-se de /ʝ/. O mesmo som pode aparecer como «inh» (caminho).',
 '["medial"]',
 '["nha","nhe","nhi","nho","nhu"]',
 '["ca-mi-nho","li-nha"]',
 '[{"word":"linha","position":"medial","syllables":["li","nha"]},{"word":"caminho","position":"medial","syllables":["ca","mi","nho"]},{"word":"vinho","position":"medial","syllables":["vi","nho"]},{"word":"sonho","position":"medial","syllables":["so","nho"]},{"word":"menina","position":"medial","syllables":["me","ni","na"]},{"word":"banho","position":"medial","syllables":["ba","nho"]},{"word":"minha","position":"medial","syllables":["mi","nha"]},{"word":"coelho","position":"medial","syllables":["co","e","lho"]},{"word":"conhecer","position":"medial","syllables":["co","nhe","cer"]},{"word":"pinheiro","position":"medial","syllables":["pi","nhei","ro"]},{"word":"fonte","position":"final","syllables":["fon","te"]},{"word":"gente","position":"final","syllables":["gen","te"]},{"word":"açaí","position":"final","syllables":["a","ça","í"]},{"word":"manacá","position":"final","syllables":["ma","na","cá"]}]',
 '["A linha é reta.","O caminho é longo.","O vinho é tinto.","A menina canta.","O banho está pronto."]',
 'É o N mais um H. Peça para sentir a língua tocar o meio da boca. Não precisa de força.',
 'Produzir /ʎ/ e generalizar para a grafia INH.',
 'Avançar quando distinguir NH de LI em 6 de 8 pares.'),

-- ================= J =================
(17, NULL,'J','''j''','consoante','/ʒ/',
 'Aproximar a língua do céu da boca fazendo um som de chiado com a voz ligada.',
 'Produção do /ʒ/ palatal sonoro.',
 'O J brasileiro soa como o gealateiro. Não é o J duro (/dʒ/) de outras línguas.',
 '["inicial","medial"]',
 '["ja","je","ji","jo","ju","ja-que-ta"]',
 '["ca-ju","a-zen-te"]',
 '[{"word":"jaqueta","position":"inicial","syllables":["ja","que","ta"]},{"word":"janela","position":"inicial","syllables":["ja","ne","la"]},{"word":"jogo","position":"inicial","syllables":["jo","go"]},{"word":"jardim","position":"inicial","syllables":["jar","dim"]},{"word":"jujuba","position":"inicial","syllables":["ju","ju","ba"]},{"word":"jiboia","position":"inicial","syllables":["ji","boi","a"]},{"word":"janta","position":"inicial","syllables":["jan","ta"]},{"word":"joelho","position":"inicial","syllables":["jo","e","lho"]},{"word":"jazz","position":"inicial","syllables":["jazz"]},{"word":"laranja","position":"final","syllables":["la","ran","ja"]},{"word":"caju","position":"final","syllables":["ca","ju"]},{"word":"beijo","position":"final","syllables":["bei","jo"]}]',
 '["A janela está aberta.","O jardim é bonito.","A menina janta às sete.","O joelho dói.","A laranja é doce."]',
 'É como um chiado com a voz ligada. Ajude com o som de «dentro» e «zero» para comparação.',
 'Produzir /ʒ/ isolado, em sílabas, palavras e frases.',
 'Avançar quando produzir sem apoio em 8 de 10 palavras.'),

-- ================= Z =================
(18, NULL,'Z','''z''','consoante','/z/',
 'Fechar os lábios com força e soltar o ar com vibração da voz.',
 'Produção do /z/ bilabial sonoro.',
 'No português brasileiro o Z inicial é pouco comum; o Z final é frequente (vez, luz, faz). Também aparece como «z» em «gelo» e «caso».',
 '["inicial","medial","final"]',
 '["za","ze","zi","zo","zu","luz"]',
 '["luz","fa-z"]',
 '[{"word":"zangado","position":"inicial","syllables":["zan","ga","do"]},{"word":"zebra","position":"inicial","syllables":["ze","bra"]},{"word":"zero","position":"inicial","syllables":["ze","ro"]},{"word":"zinco","position":"inicial","syllables":["zin","co"]},{"word":"zoológico","position":"inicial","syllables":["zo","o","ló","gi","co"]},{"word":"zurrar","position":"inicial","syllables":["zu","rrar"]},{"word":"zumbido","position":"inicial","syllables":["zum","bi","do"]},{"word":"zona","position":"inicial","syllables":["zo","na"]},{"word":"vez","position":"final","syllables":["vez"]},{"word":"luz","position":"final","syllables":["luz"]},{"word":"voz","position":"final","syllables":["voz"]},{"word":"feliz","position":"final","syllables":["fe","liz"]},{"word":"giz","position":"final","syllables":["giz"]},{"word":"cozinha","position":"medial","syllables":["co","zi","nha"]}]',
 '["A zebra corre.","O número é zero.","A luz está acesa.","A voz é forte.","A cozinha é limpa."]',
 'Lábios fechados com vibração (contraste com /s/). O Z aparece mais no final das palavras.',
 'Produzir /z/ isolado, em sílabas, palavras e frases.',
 'Avançar quando diferenciar /s/ de /z/ em 6 de 8 pares.'),

-- ================= CH =================
(19, NULL,'CH','''ch''','grupo_consonantal','/ʃ/',
 'Sopro contínuo com os dentes bem próximos, como se pedisse silêncio.',
 'Produção do /ʃ/ (digrafo CH).',
 'O CH brasileiro é um som único, e não C+H separadas. Não confundir com X em «chave» (ambos são /ʃ/).',
 '["inicial"]',
